class n{constructor(t){this.storage=t}storage;async listConversationDocuments(){const t=this.storage.listFiles().filter(e=>e.path.startsWith("Conversations/")&&e.path.toLocaleLowerCase("en-US").endsWith(".md"));return Promise.all(t.map(async e=>{const a=await this.storage.readFile(e.id);return{id:a.id,path:a.path,content:a.content,modifiedAt:a.modifiedAt}}))}async writeConversation(t){if(t.id){const a=this.storage.listFiles().find(s=>s.id===t.id);if(!a)throw new Error("Conversation file no longer exists");a.path!==t.path&&await this.storage.renameFile(t.id,t.path);const i=await this.storage.writeFile(t.id,t.content);return{id:i.id,path:i.path,content:i.content,modifiedAt:i.modifiedAt}}const e=await this.storage.createFile(t.path,t.content);return{id:e.id,path:e.path,content:e.content,modifiedAt:e.modifiedAt}}async removeConversation(t){await this.storage.deleteFile(t)}async writeAttachment(t,e){if(!t.bytes)throw new Error("Attachment bytes are unavailable");await this.storage.writeAttachment({path:e,bytes:t.bytes,mimeType:t.mimeType,contentDigest:t.digest})}async attachmentExists(t){return this.storage.listAllFiles().some(e=>e.path===t&&e.kind==="attachment")}async removeAttachment(t){const e=this.storage.listAllFiles().find(a=>a.path===t&&a.kind==="attachment");e&&await this.storage.deleteFile(e.id)}async saveUndoTransaction(t){await this.storage.writeLocalRecord("conversation-undo",t.id,t,t.expiresAt)}async loadUndoTransaction(t){return this.storage.readLocalRecord("conversation-undo",t)}async removeUndoTransaction(t){await this.storage.deleteLocalRecord("conversation-undo",t)}}export{n as VaultConversationWorkspace};
